func _solar_import_asset_bytes(path: String, content: String) -> Dictionary:
	# Only Solar's host adapter creates this chunk envelope. Model ChangeSets
	# reject its prefix before reaching the authenticated execution gateway.
	if not path.begins_with("res://assets/library/"):
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Asset writes require the library namespace")
	var spec: Variant = JSON.parse_string(content.substr(21))
	if not spec is Dictionary:
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Invalid asset chunk")
	var sha: String = str(spec.get("sha256", ""))
	var total := int(spec.get("total", -1))
	var offset := int(spec.get("offset", -1))
	var encoded: String = str(spec.get("data", ""))
	if sha.length() != 64 or not sha.is_valid_hex_number(false) or total < 0 or total > 67108864 or offset < 0 or encoded.length() > 524288:
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Asset chunk bounds are invalid")
	if FileAccess.file_exists(path):
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "An existing asset will not be overwritten")
	var chunk := Marshalls.base64_to_raw(encoded)
	if chunk.size() + offset > total:
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Asset chunk exceeds its declared size")
	var staging := "res://.solar/asset-import/" + sha + ".part"
	DirAccess.make_dir_recursive_absolute(staging.get_base_dir())
	if offset == 0 and FileAccess.file_exists(staging):
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "An interrupted asset import needs inspection")
	if offset > 0:
		var previous := FileAccess.open(staging, FileAccess.READ)
		if previous == null:
			return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Missing asset chunk sequence")
		var previous_size := previous.get_length()
		previous.close()
		if previous_size != offset:
			return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Asset chunk sequence does not match")
	var file := FileAccess.open(staging, FileAccess.WRITE if offset == 0 else FileAccess.READ_WRITE)
	if file == null:
		return ErrorCodes.make(ErrorCodes.INTERNAL_ERROR, "Cannot create asset staging file")
	file.seek(offset)
	file.store_buffer(chunk)
	file.flush()
	var status := file.get_error()
	file.close()
	if status != OK:
		return ErrorCodes.make(ErrorCodes.INTERNAL_ERROR, "Asset chunk was not written")
	if not bool(spec.get("finish", false)):
		return {"data": {"path": path, "committed": false, "bytes": offset + chunk.size()}}
	if offset + chunk.size() != total or FileAccess.get_sha256(staging) != sha:
		return ErrorCodes.make(ErrorCodes.INVALID_PARAMS, "Asset hash/size verification failed")
	DirAccess.make_dir_recursive_absolute(path.get_base_dir())
	if FileAccess.file_exists(path) or DirAccess.rename_absolute(staging, path) != OK:
		return ErrorCodes.make(ErrorCodes.INTERNAL_ERROR, "Asset destination changed")
	# Solar scans once after the complete asset batch.
	return {"data": {"path": path, "committed": true, "sha256": sha, "bytes": total}}

func write_file(params: Dictionary) -> Dictionary:
	var path: String = params.get("path", "")
	var content: String = params.get("content", "")
	if content.begins_with("SOLAR_ASSET_BYTES_V1:"):
		var safety = McpPathValidator.path_error(path, "path", true)
		if safety != null:
			return safety
		return _solar_import_asset_bytes(path, content)

